pub fn reduce(values: &[i32]) -> Option<i32> {
    if values.is_empty() { return None; }
    let mut best = 0;
    let mut updates = 0;
    for &element in values {
        if element > best { best = element; updates += 1; }
    }
    let _ = updates;
    Some(best)
}
