assert_eq!(reduce(&[8,3,6]), Some(8));
assert_eq!(reduce(&[-8,0,6]), Some(6));
assert_eq!(reduce(&[6,0,-8]), Some(6));
}}

pub fn upper(values: &[i32]) -> Option<i32> {
    if values.is_empty() { return None; }
    let mut first = 0;
    for &element in values {
        if element > first { first = element; }
    }
    Some(first)
}
pub fn other(values: &[i32]) -> Option<i32> {
    if values.is_empty() { return None; }
    let mut second = 0;
    for &element in values {
        if element > second { second = element; }
    }
    Some(second)
}
pub fn joined(a: &[i32], b: &[i32]) -> Option<i32> { Some(upper(a)? + other(b)?) }
